<script setup lang="ts">
import { ref } from 'vue'
import { request, downloadCsv } from './api'
import { fmt } from './labels'
import type { Column } from './types'
import Icon from './Icon.vue'
const props=defineProps<{projectId:string;guaranteePrice:number}>()
const emit=defineEmits<{close:[]}>()
type Scenario={revision:number;settlement_price:number;delay_days:number;rows:Record<string,unknown>[];totals:Record<string,number>;assumptions:string[];limitations:string[]}
const price=ref(Math.round(props.guaranteePrice*.9)),delay=ref(0),busy=ref(false),error=ref(''),current=ref<Scenario|null>(null),previous=ref<Scenario|null>(null)
const columns:Column[]=[{key:'policy_no',label:'保单责任'},{key:'gross_claim',label:'毛赔款',format:'money'},{key:'reinsurance_recovery',label:'再保摊回',format:'money'},{key:'hedge_recovery',label:'对冲回收',format:'money'},{key:'reinsurance_premium',label:'分保成本',format:'money'},{key:'hedge_premium',label:'期权成本',format:'money'},{key:'net_loss',label:'情景净损失',format:'money'},{key:'funding_gap',label:'赔付时资金缺口',format:'money'}]
async function calculate(){busy.value=true;error.value='';try{const result=await request<Scenario>('/workspace/scenarios',{project_id:props.projectId,settlement_price:price.value,delay_days:delay.value});previous.value=current.value;current.value=result}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const metricLabels=[['gross_claim','情景毛赔款'],['reinsurance_recovery','再保摊回'],['hedge_recovery','对冲回收'],['net_loss','含风险转移成本净损失'],['funding_gap','赔付时资金缺口'],['delay_financing_cost','示例延迟资金成本']]
</script>
<template><Teleport to="body"><div class="gg gg-overlay" @click.self="!busy&&emit('close')"><section class="gg-modal gg-scenario-dialog" role="dialog" aria-modal="true" aria-label="业务情景比较"><header><div><span class="gg-overline">同一责任 · 同一市场假设</span><h2>业务情景比较</h2></div><button class="gg-icon-btn" aria-label="关闭情景比较" :disabled="busy" @click="emit('close')"><Icon name="close"/></button></header><p class="gg-modal-description">将同一价格冲击作用于有效保单、已确认再保及对冲分配。回款延迟改变资金缺口，不改变原保险责任。</p><form @submit.prevent="calculate"><div class="gg-form-grid"><label class="gg-field"><span>假设结算价格（元/吨）</span><input v-model.number="price" type="number" min="0" max="100000" step="0.01" required/></label><label class="gg-field"><span>风险转移回款延迟（天）</span><input v-model.number="delay" type="number" min="0" max="365" step="1" required/></label></div><div class="gg-inline-actions"><button class="gg-btn" type="button" @click="price=Math.round(guaranteePrice*.9);delay=0">保障价下方10%</button><button class="gg-btn" type="button" @click="delay=30">回款延迟30天</button><button class="gg-btn gg-btn-primary" type="submit" :disabled="busy"><span v-if="busy" class="gg-spinner"/>{{ busy?'正在计算…':'计算情景' }}<Icon v-if="!busy" name="arrow" :size="15"/></button></div></form><div v-if="error" class="gg-error" role="alert"><Icon name="warning" :size="17"/>{{ error }}</div><section v-if="current" class="gg-scenario-results"><div class="gg-card-heading"><div><h2>{{ fmt(current.settlement_price) }} 元/吨 · 延迟 {{ current.delay_days }} 天</h2><p>责任快照 v{{ current.revision }} · 金额单位：元</p></div><button class="gg-text-btn" @click="downloadCsv('玉米保险业务情景',columns,current.rows)"><Icon name="download" :size="15"/>导出结果</button></div><div class="gg-scenario-metrics"><article v-for="[key,title] in metricLabels" :key="key"><span>{{ title }}</span><strong>{{ fmt(current.totals[key!]) }}</strong><small v-if="previous&&previous.revision===current.revision">上次 {{ fmt(previous.totals[key!]) }}<b v-if="current.totals[key!]!==previous.totals[key!]"> · 变化 {{ fmt(current.totals[key!]-previous.totals[key!]) }}</b></small></article></div><div v-if="previous&&previous.revision!==current.revision" class="gg-notice"><Icon name="info" :size="16"/><span>责任版本发生变化，两次结果不进行直接比较。</span></div><div class="gg-table-overflow"><table class="gg-table"><thead><tr><th v-for="col in columns" :key="col.key">{{ col.label }}</th></tr></thead><tbody><tr v-for="row in current.rows" :key="String(row.policy_id)"><td v-for="col in columns" :key="col.key">{{ col.format==='money'?fmt(row[col.key]):row[col.key] }}</td></tr></tbody></table></div><div v-for="text in [...current.assumptions,...current.limitations]" :key="text" class="gg-scenario-assumption"><Icon name="info" :size="13"/><span>{{ text }}</span></div></section><footer><span>情景研究不修改保单、不发出交易、不产生应付。</span><button class="gg-btn" :disabled="busy" @click="emit('close')">关闭</button></footer></section></div></Teleport></template>
<style scoped>.gg-scenario-dialog{width:970px}.gg-scenario-results{margin-top:27px;border-top:1px solid var(--line);padding-top:23px}.gg-scenario-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:15px 0 23px}.gg-scenario-metrics article{padding:15px;border:1px solid var(--line);border-radius:7px;background:#fbfbfe;min-width:0}.gg-scenario-metrics span{display:block;font-size:11px;color:#8995ad}.gg-scenario-metrics strong{display:block;font-size:24px;font-weight:500;color:#6a729c;margin:10px 0;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.gg-scenario-metrics small{font-size:10px;color:#a3aec4;display:block}.gg-scenario-metrics b{font-weight:500;color:#ab987b}.gg-scenario-assumption{display:flex;gap:7px;font-size:10px;color:#9caac2;margin-top:9px;line-height:1.9}.gg-scenario-assumption svg{margin-top:4px}@media(max-width:600px){.gg-scenario-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.gg-scenario-metrics article{padding:12px}.gg-scenario-metrics strong{font-size:21px}.gg-scenario-metrics span,.gg-scenario-metrics small{font-size:10px}}
</style>
